'use strict';
let vocabController=null;
const allVocabulary=()=>Object.values(VOCABULARY).flat();
const vocabularyFor=id=>id?VOCABULARY[Number(id)]||VOCABULARY[1]:allVocabulary();
const wordStatus=id=>state.vocabProgress?.[id]?.status||'new';
const vocabLabels={new:'未掌握',review:'需复习',known:'自评已掌握'};
function shuffled(items){const a=items.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
window.vocabularyQuestionBank=function(id){return vocabularyFor(id).map((w,i)=>{const sameChapter=vocabularyFor(w.chapter).filter(x=>x.id!==w.id),samePos=sameChapter.filter(x=>x.pos===w.pos),distractors=shuffled(samePos.length>=3?samePos:sameChapter).slice(0,3),cloze=i%2===1;const choices=shuffled([w,...distractors]),escaped=w.term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),sentence=w.example.replace(new RegExp('\\b'+escaped+'\\b','i'),'_____');return{id:'vocab-'+w.id,vocabId:w.id,chapter:w.chapter,kind:cloze?'语境选词':'词汇释义',q:cloze?`【语境选词】选择表达“${w.meaning}”的词或词组：${sentence}`:`【词汇释义】“${w.term}”在本章中的含义是？`,options:choices.map(x=>cloze?x.term:x.meaning),a:choices.findIndex(x=>x.id===w.id),why:`${w.term}（${w.pos}）：${w.meaning}。例句：${w.example}`};});};
window.trackVocabularyResult=function(questions,answers){state.vocabProgress||={};questions.forEach((q,i)=>{if(q.vocabId&&Number(answers[i])!==q.a){state.vocabProgress[q.vocabId]={...state.vocabProgress[q.vocabId],status:'review',updated:today()};}});};
window.mountVocabularyScore=function(qz){if(!qz?.submitted)return;const v=qz.questions.map((q,i)=>({q,answer:qz.answers[i]})).filter(x=>x.q.vocabId),b=qz.questions.map((q,i)=>({q,answer:qz.answers[i]})).filter(x=>!x.q.vocabId);if(!v.length)return;const n=v.filter(x=>Number(x.answer)===x.q.a).length,bn=b.filter(x=>Number(x.answer)===x.q.a).length,chapters=[...new Set(v.filter(x=>Number(x.answer)!==x.q.a).map(x=>x.q.chapter))];document.querySelector('.score-big')?.insertAdjacentHTML('afterend',`<div class="note vocabulary-score"><strong>词汇 ${n}/${v.length}</strong>${b.length?` · 业务 ${bn}/${b.length}`:''}<p style="margin:7px 0 0">错词已加入“需复习”；答对的词保留你的学习自评。</p>${chapters.length?`<div class="btn-row">${chapters.map(c=>`<a class="btn secondary small" href="#vocab/${c}?status=review">复习 W${c} 错词 ↗</a>`).join('')}</div>`:''}</div>`);};
window.cleanupVocabulary=function(){vocabController?.abort();vocabController=null;};
window.mountLessonVocabulary=function(id){const words=vocabularyFor(id),host=document.querySelector('.lesson-content');if(!host)return;const block=`<section class="panel lesson-vocabulary"><span class="eyebrow">VOCABULARY / WEEK ${id}</span><h2>本章25个实用词汇</h2><p class="sub">先按每天5个学习，再把词用进本章汇报和邮件。释义、例句、发音与复习标记都在词汇模块。</p><div class="vocab-chip-list">${words.slice(0,10).map(w=>`<a class="chip" href="#vocab/${id}?q=${encodeURIComponent(w.term)}">${esc(w.term)}</a>`).join('')}<span class="muted">＋15</span></div><div class="btn-row"><a class="btn small" href="#vocab/${id}">学习本章25词 ↗</a><button class="btn secondary small" data-vocab-test="${id}">本章词汇测试 · 25题</button><button class="btn light small" data-vocab-chapter-test="${id}">本章综合测验 · 27题</button></div></section>`;const audio=host.querySelector('.audio-lesson-preview');if(audio)audio.insertAdjacentHTML('afterend',block);else host.insertAdjacentHTML('afterbegin',block);};
function vocabularyCard(w,hidden){const status=wordStatus(w.id);return `<article class="panel vocab-card" data-word="${w.id}"><div class="vocab-card-head"><span class="vocab-number">${w.id.split('-')[1]}</span><span class="vocab-status ${status}">${vocabLabels[status]}</span></div><div class="vocab-term-row"><h3>${esc(w.term)}</h3><span class="chip">${esc(w.pos)}</span><button class="vocab-audio" data-vocab-speak="${w.id}" aria-label="朗读 ${esc(w.term)}">▷</button></div><div class="vocab-meaning" ${hidden?'hidden':''}>${esc(w.meaning)}</div><p class="vocab-example">${esc(w.example)}</p><div class="vocab-buttons"><button class="text-btn" data-vocab-reveal="${w.id}">${hidden?'显示释义':'遮住释义'}</button><button class="text-btn" data-vocab-example="${w.id}">听例句</button></div><div class="vocab-mastery"><button class="btn secondary small ${status==='review'?'selected':''}" data-vocab-mark="${w.id}" data-status="review" aria-pressed="${status==='review'}">再练一次</button><button class="btn light small ${status==='known'?'selected':''}" data-vocab-mark="${w.id}" data-status="known" aria-pressed="${status==='known'}">我能使用了</button></div></article>`;}
window.renderVocabulary=function(id){cleanupVocabulary();vocabController=new AbortController();const chapter=Number(id)||Number(state.vocabLastChapter)||nextCourse().id,c=course(chapter),words=vocabularyFor(c.id),params=new URLSearchParams(location.hash.split('?')[1]||''),filter=params.get('status')||'all',hide=params.get('hide')==='1',query=params.get('q')||'';state.vocabLastChapter=c.id;save();$('#main').innerHTML=pageHead('WORDS YOU CAN USE',`W${c.id} · ${c.title}的词汇`,'每章25个词汇或常用词组。先理解在工作中的意思，再朗读例句、遮住释义回忆，最后用测试检查。')+`<section class="panel vocab-overview"><div><span class="eyebrow">25 WORDS / 5 PER DAY</span><h2>每天5个，放进场景里记。</h2><p class="sub">先学本章需要的表达；词汇专项25题、章节测验27题。测验错词会自动进入复习列表。</p></div><div class="vocab-counts"><div><strong id="vocab-known-count">0</strong><span>自评已掌握</span></div><div><strong id="vocab-review-count">0</strong><span>需复习</span></div><div><strong>25</strong><span>本章词汇</span></div></div></section><div class="vocab-controls"><div><label class="field" for="vocab-chapter">学习章节</label><select id="vocab-chapter">${COURSES.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>W${x.id} · ${x.title}</option>`).join('')}</select></div><div><label class="field" for="vocab-search">搜索本章词汇</label><input type="text" id="vocab-search" value="${esc(query)}" placeholder="英文、中文或例句关键词"></div><label class="check-line"><input class="task-check" type="checkbox" id="vocab-hide" ${hide?'checked':''}>遮住全部释义</label></div><div class="filter-bar">${[['all','全部'],['new','未掌握'],['review','需复习'],['known','自评已掌握']].map(([v,t])=>`<button class="filter-btn ${filter===v?'active':''}" data-vocab-filter="${v}">${t}</button>`).join('')}<button class="btn secondary small" style="margin-left:auto" data-vocab-test="${c.id}">词汇专项 · 25题</button><button class="btn light small" data-vocab-export="${c.id}">导出本章词表 ↓</button></div><div class="vocab-grid">${words.map(w=>vocabularyCard(w,hide)).join('')}</div><div class="empty" id="vocab-empty" hidden>当前筛选下没有词汇。换一个筛选，或到测验中找出需要复习的词。</div><div class="note">“我能使用了”是学习自评。建议至少能不看释义说出意思，并把词用进一个新的业务句子。发音使用浏览器合成语音，声音取决于设备。</div><div class="btn-row"><a class="btn secondary" href="#lesson/${c.id}">返回本章课程</a><button class="btn" data-vocab-chapter-test="${c.id}">做本章27题测验 ↗</button></div>`;
function updateCards(){const search=$('#vocab-search').value.trim().toLowerCase();words.forEach(w=>{const card=document.querySelector(`[data-word="${w.id}"]`),status=wordStatus(w.id);card.hidden=(filter!=='all'&&status!==filter)||!(w.term+' '+w.meaning+' '+w.example).toLowerCase().includes(search);const badge=card.querySelector('.vocab-status');badge.textContent=vocabLabels[status];badge.className='vocab-status '+status;card.querySelectorAll('[data-vocab-mark]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.status===status));b.classList.toggle('selected',b.dataset.status===status);});});$('#vocab-known-count').textContent=words.filter(w=>wordStatus(w.id)==='known').length;$('#vocab-review-count').textContent=words.filter(w=>wordStatus(w.id)==='review').length;$('#vocab-empty').hidden=words.some(w=>!document.querySelector(`[data-word="${w.id}"]`).hidden);}
updateCards();$('#vocab-search').addEventListener('input',updateCards);$('#vocab-chapter').addEventListener('change',()=>{location.hash='#vocab/'+$('#vocab-chapter').value;});$('#vocab-hide').addEventListener('change',()=>{document.querySelectorAll('.vocab-meaning').forEach(el=>el.hidden=$('#vocab-hide').checked);document.querySelectorAll('[data-vocab-reveal]').forEach(b=>b.textContent=$('#vocab-hide').checked?'显示释义':'遮住释义');});$('#main').addEventListener('click',e=>{const b=e.target.closest('[data-vocab-filter],[data-vocab-reveal],[data-vocab-mark]');if(!b)return;if(b.dataset.vocabFilter){const next=new URLSearchParams();next.set('status',b.dataset.vocabFilter);if($('#vocab-hide').checked)next.set('hide','1');if($('#vocab-search').value)next.set('q',$('#vocab-search').value);location.hash=`#vocab/${c.id}?${next}`;}if(b.dataset.vocabReveal){const meaning=document.querySelector(`[data-word="${b.dataset.vocabReveal}"] .vocab-meaning`);meaning.hidden=!meaning.hidden;b.textContent=meaning.hidden?'显示释义':'遮住释义';}if(b.dataset.vocabMark){state.vocabProgress||={};const current=wordStatus(b.dataset.vocabMark),status=b.dataset.status;state.vocabProgress[b.dataset.vocabMark]={status:current===status?'new':status,updated:today()};save();updateCards();}},{signal:vocabController.signal});};
window.mountVocabularyTestPanel=function(){if(activeQuiz)return;const hero=document.querySelector('#main .hero-grid');if(!hero)return;hero.insertAdjacentHTML('afterend',`<section class="panel vocab-test-panel"><div><span class="eyebrow">VOCABULARY CHECK / 25 QUESTIONS</span><h2>词汇也要单独测一次</h2><p class="sub">25题覆盖英文释义与业务语境选词。选本章检查学习成果，选跨章节检验迁移；错词自动加入复习。</p></div><div><label class="field" for="vocab-test-chapter">测试范围</label><select id="vocab-test-chapter"><option value="0">跨12章随机25词</option>${COURSES.map(c=>`<option value="${c.id}">W${c.id} · ${c.title}</option>`).join('')}</select><button class="btn small" style="margin-top:13px" data-vocab-test="selected">开始25题词汇测验 ↗</button></div></section>`);};
window.mountVocabularyHome=function(){const c=nextCourse(),host=document.querySelector('#main .hero-grid');if(!host)return;host.insertAdjacentHTML('afterend',`<a class="panel vocab-home-link" href="#vocab/${c.id}"><span class="eyebrow">TODAY'S VOCABULARY</span><strong>本章25个实用词汇，今天先学5个。</strong><span>释义 · 例句 · 发音 · 错词复习 ↗</span></a>`);};
document.addEventListener('click',e=>{const b=e.target.closest('[data-vocab-test],[data-vocab-chapter-test],[data-vocab-export],[data-vocab-speak],[data-vocab-example]');if(!b)return;if(b.dataset.vocabTest){const id=b.dataset.vocabTest==='selected'?Number($('#vocab-test-chapter').value):Number(b.dataset.vocabTest);startQuiz(id||undefined,{vocabularyOnly:true});}if(b.dataset.vocabChapterTest)startQuiz(Number(b.dataset.vocabChapterTest));if(b.dataset.vocabExport){const id=Number(b.dataset.vocabExport),words=vocabularyFor(id);download(`W${id}_实用词汇25个.md`,`# W${id} ${course(id).title}｜词汇\n\n${words.map((w,i)=>`${i+1}. **${w.term}**（${w.pos}）${w.meaning}\n\n   ${w.example}`).join('\n\n')}`);}const id=b.dataset.vocabSpeak||b.dataset.vocabExample;if(id){const w=allVocabulary().find(x=>x.id===id);if(!w)return;if(!('speechSynthesis'in window))return toast('此浏览器不支持朗读，可先阅读例句或使用已下载的课程音频。');speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(b.dataset.vocabExample?w.example:w.term);utter.lang='en-US';utter.rate=.85;utter.onerror=()=>toast('合成朗读不可用，请检查设备语音设置。');speechSynthesis.speak(utter);}});
